begin;
create extension if not exists pgtap with schema extensions;
select plan(10);
select has_function('public','edit_meeting_invitation_with_place',array['uuid','uuid','integer','timestamp with time zone','text','text','jsonb','text'],'pending invitation edit RPC exists');
insert into auth.users(id,email) values ('e1111111-1111-1111-1111-111111111111','invite-a@example.test'),('e2222222-2222-2222-2222-222222222222','invite-b@example.test');
insert into public.profiles(id,owner_id,display_name) values ('eaaaaaaa-1111-1111-1111-111111111111','e1111111-1111-1111-1111-111111111111','Alex'),('ebbbbbbb-2222-2222-2222-222222222222','e2222222-2222-2222-2222-222222222222','Jordan');
set local role authenticated;
select set_config('request.jwt.claim.sub','e1111111-1111-1111-1111-111111111111',true);
create temp table t as select public.open_conversation('ebbbbbbb-2222-2222-2222-222222222222') id;
create temp table p as select '{"name":"Library","address":"125 W Main St, Grove City, PA 16127","latitude":41.1578,"longitude":-80.0887}'::jsonb place;
create temp table m as select public.create_meeting_with_place((select id from t),'e0000000-0000-0000-0000-000000000001','2099-01-01','UTC','Library',(select place from p),'Board') value;
select public.edit_meeting_invitation_with_place((select (value->>'id')::uuid from m),'e0000000-0000-0000-0000-000000000002',1,'2099-01-02','UTC','Library',(select place from p),'Meet upstairs');
select is(public.get_meeting((select (value->>'id')::uuid from m))->>'status','pending','edit remains pending');
select is(public.get_meeting((select (value->>'id')::uuid from m))->'revision'->>'note','Meet upstairs','current offered facts update');
select is(public.create_meeting_with_place((select id from t),'e0000000-0000-0000-0000-000000000001','2099-01-01','UTC','Library',(select place from p),'Board')->>'id',(select value->>'id' from m),'original send retries survive edits');
select lives_ok($$select public.edit_meeting_invitation_with_place((select (value->>'id')::uuid from m),'e0000000-0000-0000-0000-000000000002',1,'2099-01-02','UTC','Library',(select place from p),'Meet upstairs')$$,'edit acknowledgement retries');
select set_config('request.jwt.claim.sub','e2222222-2222-2222-2222-222222222222',true);
select throws_ok($$select public.edit_meeting_invitation_with_place((select (value->>'id')::uuid from m),gen_random_uuid(),2,'2099-01-03','UTC','Library',(select place from p),'Other')$$,'42501',null,'recipient cannot edit invitation');
select throws_ok($$select public.respond_to_meeting((select (value->>'id')::uuid from m),gen_random_uuid(),1,'confirmed')$$,'PT409',null,'old version cannot be accepted');
select public.respond_to_meeting((select (value->>'id')::uuid from m),gen_random_uuid(),2,'confirmed');
select is(public.get_meeting((select (value->>'id')::uuid from m))->'revision'->>'note','Meet upstairs','recipient accepts latest revision');
select set_config('request.jwt.claim.sub','e1111111-1111-1111-1111-111111111111',true);
select throws_ok($$select public.edit_meeting_invitation_with_place((select (value->>'id')::uuid from m),gen_random_uuid(),3,'2099-01-03','UTC','Library',(select place from p),'Other')$$,'PT409',null,'accepted invitation requires agreed change flow');
reset role;
select is((select count(*)::integer from public.meeting_revisions where meeting_id=(select (value->>'id')::uuid from m)),2,'original and edited facts remain immutable');
select * from finish();
rollback;
